begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(12);
select is((select count(*)::int from pg_tables where schemaname='public' and rowsecurity and tablename in ('expenses','expense_categories','cashbox_transfers','payment_refunds','financial_configuration_events')),5,'Operation tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.expenses','insert'),'Direct expense mutation denied');
select ok(not has_table_privilege('authenticated','public.payment_refunds','select'),'Raw refund numeric data hidden');
select is((select public from storage.buckets where id='finance-receipts'),false,'Receipt bucket is private');
select is((select count(*)::int from pg_policies where schemaname='storage' and policyname in ('finance_receipts_insert','finance_receipts_read')),2,'Receipt policies installed without update/delete policy');
create temporary table ops(label text primary key,id uuid);grant select,insert on ops to authenticated;
insert into auth.users(id,email) values('99999200-0000-0000-0000-000000000001','native-operations@example.test');
set local role authenticated;set local request.jwt.claim.sub='99999200-0000-0000-0000-000000000001';
insert into ops select 'tenant',public.create_business('Native operations');
insert into ops select 'branch',id from public.branches limit 1;
insert into ops select 'source',public.save_cashbox((select id from ops where label='tenant'),null,gen_random_uuid(),jsonb_build_object('name','Source','cashbox_type','cash','branch_id',(select id from ops where label='branch')));
insert into ops select 'destination',public.save_cashbox((select id from ops where label='tenant'),null,gen_random_uuid(),jsonb_build_object('name','Destination','cashbox_type','cash','branch_id',(select id from ops where label='branch')));
select public.post_cashbox_entry((select id from ops where label='tenant'),(select id from ops where label='source'),gen_random_uuid(),'opening_balance','100','Initial reserve');
insert into ops select 'transfer',public.post_cashbox_transfer((select id from ops where label='tenant'),gen_random_uuid(),(select id from ops where label='source'),(select id from ops where label='destination'),'30.10','2026-10-22T00:00:00Z','Move to destination');
set constraints all immediate;
select is(public.cashbox_details((select id from ops where label='tenant'),(select id from ops where label='source'))->>'balance','69.90','Transfer debits exact source');
select is(public.cashbox_details((select id from ops where label='tenant'),(select id from ops where label='destination'))->>'balance','30.10','Transfer credits exact destination');
set constraints all deferred;
select throws_ok($$select public.post_cashbox_transfer((select id from ops where label='tenant'),gen_random_uuid(),(select id from ops where label='source'),(select id from ops where label='destination'),'70','2026-10-22T00:00:00Z','Too much transfer')$$,'P0001','Insufficient cashbox balance','Insufficient transfer rolls back');
set constraints all deferred;
select lives_ok($$select public.reverse_financial_transaction((select id from ops where label='tenant'),(public.financial_operation_details((select id from ops where label='tenant'),'transfer',(select id from ops where label='transfer'))->>'transaction_id')::uuid,gen_random_uuid(),to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'Correct native transfer')$$,'Transfer reversal commits opposite legs');
set constraints all immediate;
select is(public.cashbox_details((select id from ops where label='tenant'),(select id from ops where label='source'))->>'balance','100.00','Reversal restores source');
select is(public.cashbox_details((select id from ops where label='tenant'),(select id from ops where label='destination'))->>'balance','0.00','Reversal restores destination');
reset role;
select throws_ok($$delete from public.cashbox_transfers where id=(select id from ops where label='transfer')$$,'23514','Posted financial history is immutable','Transfer history cannot be deleted');
select * from finish();rollback;
